/**
 * FinanceQuizWord brand mark — the site's logo artwork, rendered from the PNG
 * generated by scripts/make-logo-assets.ps1 (the supplied SVG is a 512 canvas
 * wrapping a 1.7 MB raster, far too heavy for a 40 px mark).
 * Decorative: the link and the page headings already carry the name.
 */
const LOGO_SRC = '/images/logo-financequizword.png';

export default function Logo({ className = '' }) {
  return (
    <img
      className={className}
      src={LOGO_SRC}
      alt=""
      aria-hidden="true"
      width="40"
      height="40"
      draggable="false"
      decoding="async"
    />
  );
}
